23	ReplicatedMergeMutateTaskBase::PrepareResult MergeFromLogEntryTask::prepare()
24	{
25	    LOG_TRACE(log, "Executing log entry to merge parts {} to {}",
26	        fmt::join(entry.source_parts, ", "), entry.new_part_name);
27	
28	    const auto storage_settings_ptr = storage.getSettings();
29	
30	    if (storage_settings_ptr->always_fetch_merged_part)
31	    {
32	        LOG_INFO(log, "Will fetch part {} because setting 'always_fetch_merged_part' is true", entry.new_part_name);
33	        return PrepareResult{
34	            .prepared_successfully = false,
35	            .need_to_check_missing_part_in_fetch = true,
36	            .part_log_writer = {}
37	        };
38	    }
39	
40	    if (entry.merge_type == MergeType::TTLRecompress &&
41	        (time(nullptr) - entry.create_time) <= storage_settings_ptr->try_fetch_recompressed_part_timeout.totalSeconds() &&
42	        entry.source_replica != storage.replica_name)
43	    {
44	        LOG_INFO(log, "Will try to fetch part {} until '{}' because this part assigned to recompression merge. "
45	            "Source replica {} will try to merge this part first", entry.new_part_name,
46	            DateLUT::instance().timeToString(entry.create_time + storage_settings_ptr->try_fetch_recompressed_part_timeout.totalSeconds()), entry.source_replica);
47	            /// Waiting other replica to recompress part. No need to check it.
48	            return PrepareResult{
49	                .prepared_successfully = false,
50	                .need_to_check_missing_part_in_fetch = false,
51	                .part_log_writer = {}
52	            };
53	    }
54	
55	    /// In some use cases merging can be more expensive than fetching
56	    /// and it may be better to spread merges tasks across the replicas
57	    /// instead of doing exactly the same merge cluster-wise
58	
59	    if (storage.merge_strategy_picker.shouldMergeOnSingleReplica(entry))
60	    {
61	        std::optional<String> replica_to_execute_merge = storage.merge_strategy_picker.pickReplicaToExecuteMerge(entry);
62	        if (replica_to_execute_merge)
63	        {
64	            LOG_DEBUG(log,
65	                "Prefer fetching part {} from replica {} due to execute_merges_on_single_replica_time_threshold",
66	                entry.new_part_name, replica_to_execute_merge.value());
67	
68	            return PrepareResult{
69	                .prepared_successfully = false,
70	                .need_to_check_missing_part_in_fetch = true,
71	                .part_log_writer = {}
72	            };
73	        }
74	    }
75	
76	
77	    for (const String & source_part_name : entry.source_parts)
78	    {
79	        MergeTreeData::DataPartPtr source_part_or_covering = storage.getActiveContainingPart(source_part_name);
80	
81	        if (!source_part_or_covering)
82	        {
83	            /// We do not have one of source parts locally, try to take some already merged part from someone.
84	            LOG_DEBUG(log, "Don't have all parts (at least part {} is missing) for merge {}; will try to fetch it instead", source_part_name, entry.new_part_name);
85	            return PrepareResult{
86	                .prepared_successfully = false,
87	                .need_to_check_missing_part_in_fetch = true,
88	                .part_log_writer = {}
89	            };
90	        }
91	
92	        if (source_part_or_covering->name != source_part_name)
93	        {
94	            /// We do not have source part locally, but we have some covering part. Possible options:
95	            /// 1. We already have merged part (source_part_or_covering->name == new_part_name)
96	            /// 2. We have some larger merged part which covers new_part_name (and therefore it covers source_part_name too)
97	            /// 3. We have two intersecting parts, both cover source_part_name. It's logical error.
98	            /// TODO Why 1 and 2 can happen? Do we need more assertions here or somewhere else?
99	            constexpr const char * message = "Part {} is covered by {} but should be merged into {}. This shouldn't happen often.";
100	            LOG_WARNING(log, fmt::runtime(message), source_part_name, source_part_or_covering->name, entry.new_part_name);
101	            if (!source_part_or_covering->info.contains(MergeTreePartInfo::fromPartName(entry.new_part_name, storage.format_version)))
102	                throw Exception(ErrorCodes::LOGICAL_ERROR, message, source_part_name, source_part_or_covering->name, entry.new_part_name);
103	
104	            return PrepareResult{
105	                .prepared_successfully = false,
106	                .need_to_check_missing_part_in_fetch = true,
107	                .part_log_writer = {}
108	            };
109	        }
110	
111	        parts.push_back(source_part_or_covering);
112	    }
113	
114	    /// All source parts are found locally, we can execute merge
115	
116	    if (entry.create_time + storage_settings_ptr->prefer_fetch_merged_part_time_threshold.totalSeconds() <= time(nullptr))
117	    {
118	        /// If entry is old enough, and have enough size, and part are exists in any replica,
119	        ///  then prefer fetching of merged part from replica.
120	
121	        size_t sum_parts_bytes_on_disk = 0;
122	        for (const auto & item : parts)
123	            sum_parts_bytes_on_disk += item->getBytesOnDisk();
124	
125	        if (sum_parts_bytes_on_disk >= storage_settings_ptr->prefer_fetch_merged_part_size_threshold)
126	        {
127	            String replica = storage.findReplicaHavingPart(entry.new_part_name, true);    /// NOTE excessive ZK requests for same data later, may remove.
128	            if (!replica.empty())
129	            {
130	                LOG_DEBUG(log, "Prefer to fetch {} from replica {}", entry.new_part_name, replica);
131	                /// We found covering part, no checks for missing part.
132	                return PrepareResult{
133	                    .prepared_successfully = false,
134	                    .need_to_check_missing_part_in_fetch = false,
135	                    .part_log_writer = {}
136	                };
137	            }
138	        }
139	    }
140	
141	    /// Start to make the main work
142	    size_t estimated_space_for_merge = MergeTreeDataMergerMutator::estimateNeededDiskSpace(parts);
143	
144	    /// Can throw an exception while reserving space.
145	    IMergeTreeDataPart::TTLInfos ttl_infos;
146	    size_t max_volume_index = 0;
147	    for (auto & part_ptr : parts)
148	    {
149	        ttl_infos.update(part_ptr->ttl_infos);
150	        max_volume_index = std::max(max_volume_index, part_ptr->data_part_storage->getVolumeIndex(*storage.getStoragePolicy()));
151	    }
152	
153	    /// It will live until the whole task is being destroyed
154	    table_lock_holder = storage.lockForShare(RWLockImpl::NO_QUERY, storage_settings_ptr->lock_acquire_timeout_for_background_operations);
155	
156	    StorageMetadataPtr metadata_snapshot = storage.getInMemoryMetadataPtr();
157	
158	    auto future_merged_part = std::make_shared<FutureMergedMutatedPart>(parts, entry.new_part_type);
159	    if (future_merged_part->name != entry.new_part_name)
160	    {
161	        throw Exception("Future merged part name " + backQuote(future_merged_part->name) + " differs from part name in log entry: "
162	            + backQuote(entry.new_part_name), ErrorCodes::BAD_DATA_PART_NAME);
163	    }
164	
165	    std::optional<CurrentlySubmergingEmergingTagger> tagger;
166	    ReservationSharedPtr reserved_space = storage.balancedReservation(
167	        metadata_snapshot,
168	        estimated_space_for_merge,
169	        max_volume_index,
170	        future_merged_part->name,
171	        future_merged_part->part_info,
172	        future_merged_part->parts,
173	        &tagger,
174	        &ttl_infos);
175	
176	    if (!reserved_space)
177	        reserved_space = storage.reserveSpacePreferringTTLRules(
178	            metadata_snapshot, estimated_space_for_merge, ttl_infos, time(nullptr), max_volume_index);
179	
180	    future_merged_part->uuid = entry.new_part_uuid;
181	    future_merged_part->updatePath(storage, reserved_space.get());
182	    future_merged_part->merge_type = entry.merge_type;
183	
184	    if (storage_settings_ptr->allow_remote_fs_zero_copy_replication)
185	    {
186	        if (auto disk = reserved_space->getDisk(); disk->supportZeroCopyReplication())
187	        {
188	            String dummy;
189	            if (!storage.findReplicaHavingCoveringPart(entry.new_part_name, true, dummy).empty())
190	            {
191	                LOG_DEBUG(log, "Merge of part {} finished by some other replica, will fetch merged part", entry.new_part_name);
192	                /// We found covering part, no checks for missing part.
193	                return PrepareResult{
194	                    .prepared_successfully = false,
195	                    .need_to_check_missing_part_in_fetch = false,
196	                    .part_log_writer = {}
197	                };
198	            }
199	
200	            zero_copy_lock = storage.tryCreateZeroCopyExclusiveLock(entry.new_part_name, disk);
201	
202	            if (!zero_copy_lock)
203	            {
204	                LOG_DEBUG(log, "Merge of part {} started by some other replica, will wait it and fetch merged part", entry.new_part_name);
205	                /// Don't check for missing part -- it's missing because other replica still not
206	                /// finished merge.
207	                return PrepareResult{
208	                    .prepared_successfully = false,
209	                    .need_to_check_missing_part_in_fetch = false,
210	                    .part_log_writer = {}
211	                };
212	            }
213	        }
214	    }
215	
216	    /// Account TTL merge
217	    if (isTTLMergeType(future_merged_part->merge_type))
218	        storage.getContext()->getMergeList().bookMergeWithTTL();
219	
220	    auto table_id = storage.getStorageID();
221	
222	    /// Add merge to list
223	    const Settings & settings = storage.getContext()->getSettingsRef();
224	    merge_mutate_entry = storage.getContext()->getMergeList().insert(
225	        storage.getStorageID(),
226	        future_merged_part,
227	        settings);
228	
229	    transaction_ptr = std::make_unique<MergeTreeData::Transaction>(storage, NO_TRANSACTION_RAW);
230	    stopwatch_ptr = std::make_unique<Stopwatch>();
231	
232	    merge_task = storage.merger_mutator.mergePartsToTemporaryPart(
233	            future_merged_part,
234	            metadata_snapshot,
235	            merge_mutate_entry.get(),
236	            {} /* projection_merge_list_element */,
237	            table_lock_holder,
238	            entry.create_time,
239	            storage.getContext(),
240	            reserved_space,
241	            entry.deduplicate,
242	            entry.deduplicate_by_columns,
243	            storage.merging_params,
244	            NO_TRANSACTION_PTR);
245	
246	
247	    /// Adjust priority
248	    for (auto & item : future_merged_part->parts)
249	        priority += item->getBytesOnDisk();
250	
251	    return {true, true, [this, stopwatch = *stopwatch_ptr] (const ExecutionStatus & execution_status)
252	    {
253	        storage.writePartLog(
254	            PartLogElement::MERGE_PARTS, execution_status, stopwatch.elapsed(),
255	            entry.new_part_name, part, parts, merge_mutate_entry.get());
256	    }};
257	}
