260	bool MergeFromLogEntryTask::finalize(ReplicatedMergeMutateTaskBase::PartLogWriter write_part_log)
261	{
262	    part = merge_task->getFuture().get();
263	    auto builder = merge_task->getBuilder();
264	
265	    /// Task is not needed
266	    merge_task.reset();
267	
268	    storage.merger_mutator.renameMergedTemporaryPart(part, parts, NO_TRANSACTION_PTR, *transaction_ptr, builder);
269	
270	    try
271	    {
272	        storage.checkPartChecksumsAndCommit(*transaction_ptr, part);
273	    }
274	    catch (const Exception & e)
275	    {
276	        if (MergeTreeDataPartChecksums::isBadChecksumsErrorCode(e.code()))
277	        {
278	            transaction_ptr->rollback();
279	
280	            ProfileEvents::increment(ProfileEvents::DataAfterMergeDiffersFromReplica);
281	
282	            LOG_ERROR(log,
283	                "{}. Data after merge is not byte-identical to data on another replicas. There could be several reasons:"
284	                " 1. Using newer version of compression library after server update."
285	                " 2. Using another compression method."
286	                " 3. Non-deterministic compression algorithm (highly unlikely)."
287	                " 4. Non-deterministic merge algorithm due to logical error in code."
288	                " 5. Data corruption in memory due to bug in code."
289	                " 6. Data corruption in memory due to hardware issue."
290	                " 7. Manual modification of source data after server startup."
291	                " 8. Manual modification of checksums stored in ZooKeeper."
292	                " 9. Part format related settings like 'enable_mixed_granularity_parts' are different on different replicas."
293	                " We will download merged part from replica to force byte-identical result.",
294	                getCurrentExceptionMessage(false));
295	
296	            write_part_log(ExecutionStatus::fromCurrentException());
297	
298	            if (storage.getSettings()->detach_not_byte_identical_parts)
299	                storage.forgetPartAndMoveToDetached(std::move(part), "merge-not-byte-identical");
300	            else
301	                storage.tryRemovePartImmediately(std::move(part));
302	
303	            /// No need to delete the part from ZK because we can be sure that the commit transaction
304	            /// didn't go through.
305	
306	            return false;
307	        }
308	
309	        throw;
310	    }
311	
312	    if (zero_copy_lock)
313	        zero_copy_lock->lock->unlock();
314	
315	    /** Removing old parts from ZK and from the disk is delayed - see ReplicatedMergeTreeCleanupThread, clearOldParts.
316	     */
317	
318	    /** With `ZSESSIONEXPIRED` or `ZOPERATIONTIMEOUT`, we can inadvertently roll back local changes to the parts.
319	     * This is not a problem, because in this case the merge will remain in the queue, and we will try again.
320	     */
321	    storage.merge_selecting_task->schedule();
322	    ProfileEvents::increment(ProfileEvents::ReplicatedPartMerges);
323	
324	    write_part_log({});
325	    storage.incrementMergedPartsProfileEvent(part->getType());
326	
327	    return true;
328	}
